/** An icon as an SVG string. Decorative: pair it with visible text or an aria-label. */
export function icon(name) {
  return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" ` +
    `stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${PATHS[name]}</svg>`;
}

const art = (cls, viewBox, d) => `<svg class="${cls}" viewBox="${viewBox}" fill="currentColor" ` +
  `aria-hidden="true" focusable="false"><path d="${d}"/></svg>`;

/** The icon for a movement pattern; unknown patterns get the accessory icon. */
export const patternIcon = pattern => art('icon pattern-art', ...(PATTERNS[pattern] ?? PATTERNS.accessory));

/** The logo mark, for the Board header. Decorative, like the icons. */
export const logoMark = () => art('icon', '23.9 24.2 47 47', LOGO);
